"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[94291],{94291:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<RestaurantCard\\n  cover=\\"/assets/snippets/location/73082bea3896883a45ce59793d516d9e.jpg\\"\\n  title=\\"Yo-Chi\\"\\n  cuisine=\\"Dessert\\"\\n  address=\\"Gateway Plaza, Tenancy 05-13, Alfred St, 1 Macquarie Pl, Sydney NSW 2000 Australia\\"\\n  rating=3.5\\n  tags=\\"cafe\\"\\n/>\\n</center>\\n\\n## Review\\nWas really thirsty at the time and spotted this well-known <mark>yogurt ice cream</mark> shop, so we went in.\\n\\nThe owner immediately asked if it was our first visit.  \\nWhen we said yes, they welcomed us warmly and offered to let us sample a few flavors.  \\nWe tried a little of each and they kindly explained how the ordering system works.\\n\\n```adcard\\n```\\nThe system is simple:  \\ngrab a cup, fill it with as much yogurt as you like in any flavor combination,  \\nchoose your <mark>toppings</mark>, and it\'s <mark>charged by weight</mark>.\\n\\nWe\'re not big topping people so we kept it simple.  \\nThe taste was classic yogurt — exactly as expected — and being so thirsty at the time, we finished it in no time.  \\n## Pictures\\n<pictures>\\n<img src=\\"/assets/snippets/location/73082bea3896883a45ce59793d516d9e.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Yo-Chi\\">\\n<img src=\\"/assets/snippets/location/6333b9aeb5324ca75ce9d231ecebf5cd.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Yo-Chi\\">\\n</pictures>\\n"}')}}]);